const body = $input.first().json.body || {};

// Reject missing or obviously invalid email
if (!body.email || !String(body.email).includes('@')) {
  throw new Error('email is required and must contain @');
}

// Normalise phone to E.164 (best-effort: handles 10-digit US, strips formatting)
let phone = String(body.phone || '').replace(/\D/g, '');
if (phone.length === 10) phone = '1' + phone;
if (phone.length >= 10) phone = '+' + phone;
else phone = '';

// Split composite name field into first / last
const fullName = String(body.name || '');
const firstName = (body.firstName || fullName.split(' ')[0] || 'Unknown').trim();
const lastName = (body.lastName || fullName.split(' ').slice(1).join(' ') || '-').trim();

return [{
  json: {
    email: body.email.trim().toLowerCase(),
    firstName,
    lastName,
    phone,
    source: body.source || ''
  }
}];
